const readRequests = async () => {
  try { return JSON.parse(await readFile(requestsFile, 'utf8')) }
  catch (error) { if (error.code === 'ENOENT') return []; throw error }
}
const saveRequests = async requests => {
  await mkdir(dataDirectory, { recursive: true })
  for (const entry of requests) {
    entry.timeline=(entry.timeline||[]).slice(-200).map(event=>({...event,title:cleanText(event.title,180),text:cleanText(event.text,5000)}))
    entry.emails=(entry.emails||[]).slice(-200).map(mail=>({...mail,from:cleanText(mail.from,180),to:cleanText(mail.to,180),subject:cleanText(mail.subject,300),text:cleanText(mail.text,10000)}))
    const latestAction=(entry.timeline||[]).at(-1)
    if(latestAction?.title==='Absage angefragt'){
      delete entry.bookedAppointmentId
      delete entry.consultationAppointmentId
      delete entry.consultationCompletedAt
    }
  }
  await writeFile(requestsFile, JSON.stringify(requests, null, 2), 'utf8')
}
