        if(typeof input.status==='string')entry.status=cleanText(input.status,50)
        const requestEntry=requests.find(item=>item.id===entry.requestId),now=new Date().toISOString()
        if(input.completeConsultation&&entry.type==='consultation'&&requestEntry){entry.status='Erledigt';requestEntry.consultationCompletedAt=now;requestEntry.status='Beratung abgeschlossen';requestEntry.timeline=[...(requestEntry.timeline||[]),{title:'Beratung abgeschlossen',text:'Haupttermin-Vorschläge sind jetzt freigeschaltet.',createdAt:now}].slice(-200)}
        if(input.status==='Storniert'&&requestEntry){if(entry.type==='consultation'){delete requestEntry.consultationAppointmentId;delete requestEntry.consultationCompletedAt}else delete requestEntry.bookedAppointmentId;requestEntry.status='Neu';delete requestEntry.readAt;requestEntry.activityAt=now;requestEntry.timeline=[...(requestEntry.timeline||[]),{title:'Termin vom Studio abgesagt',text:new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',dateStyle:'full',timeStyle:'short'}).format(new Date(entry.start))+' Uhr',createdAt:now}].slice(-200)}
        if(input.notifyCustomer&&entry.email&&requestEntry){const publicUrl=String(process.env.PUBLIC_URL||'https://tattoosfumato.de').replace(/\/$/,''),manageUrl=`${publicUrl}/terminverwaltung?termin=${encodeURIComponent(entry.id)}&token=${encodeURIComponent(appointmentToken(entry.id))}`,subject=input.status==='Storniert'?'Dein Termin wurde abgesagt':'Dein Termin wurde verschoben',text=input.status==='Storniert'?`Hallo ${entry.clientName.split(/\s+/)[0]},\n\ndein Termin am ${new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',dateStyle:'full',timeStyle:'short'}).format(new Date(entry.start))} Uhr wurde vom Studio abgesagt. Wir melden uns wegen eines neuen Termins bei dir.`:`Hallo ${entry.clientName.split(/\s+/)[0]},\n\ndein Termin wurde auf ${new Intl.DateTimeFormat('de-DE',{timeZone:'Europe/Berlin',dateStyle:'full',timeStyle:'short'}).format(new Date(entry.start))} Uhr verschoben.`;const sent=await sendRequestMail({requestEntry,to:entry.email,subject,text,actionUrl:input.status==='Storniert'?'':manageUrl,actionLabel:'Termin verwalten'});requestEntry.emails=[...(requestEntry.emails||[]),{id:`MAIL-${Date.now().toString(36).toUpperCase()}`,direction:'outbound',to:entry.email,subject:sent.subject,text:sent.text,messageId:sent.messageId,createdAt:now}].slice(-200)}
        await Promise.all([saveAppointments(entries),saveRequests(requests)])
